// The fix the diagnostic's note points to: borrow instead of taking ownership.
fn total(values: &[i32]) -> i32 {
    values.iter().sum()
}

fn main() {
    let readings = vec![3, 4, 5];
    let sum = total(&readings);
    println!("{sum} from {} readings, first {}", readings.len(), readings[0]);
}

